// GetLanguageLocale returns the system.Locale for the given language.
func GetLanguageLocale(language string) system.Locale {
	if language == "" {
		return system.Locale{}
	}
	// Only the primary locale is relevant.
	primaryLanguage := strings.Split(language, ",")[0]
	langParts := strings.Split(strings.ToLower(primaryLanguage), "-")
	for _, langPart := range langParts {
		if len(langPart) == 2 {
			if slices.Contains(RightToLeftLanguages2, langPart) {
				return system.Locale{
					Language:  language,
					Direction: system.RTL,
				}
			}
		}
		if len(langPart) == 3 {
			if slices.Contains(RightToLeftLanguages3, langPart) {
				return system.Locale{
					Language:  language,
					Direction: system.RTL,
				}
			}
		}
	}
	return system.Locale{
		Language:  language,
		Direction: system.LTR,
	}
}
